CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(140) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('patient','doctor','admin')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS patient_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,birth_date DATE,sex VARCHAR(20),phone VARCHAR(40),blood_type VARCHAR(8));
CREATE TABLE IF NOT EXISTS clinics(id SERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,address TEXT NOT NULL,phone VARCHAR(40),latitude NUMERIC(9,6),longitude NUMERIC(9,6),hours TEXT);
CREATE TABLE IF NOT EXISTS specialties(id SERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS doctors(id SERIAL PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE SET NULL,clinic_id INTEGER REFERENCES clinics(id),specialty_id INTEGER REFERENCES specialties(id),experience_years INTEGER NOT NULL DEFAULT 0,bio TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS appointments(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id),doctor_id INTEGER NOT NULL REFERENCES doctors(id),starts_at TIMESTAMPTZ NOT NULL,reason TEXT DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'Запланирована',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS appointments_doctor_time_idx ON appointments(doctor_id,starts_at);
CREATE TABLE IF NOT EXISTS metric_types(id SERIAL PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,label VARCHAR(80) NOT NULL,unit VARCHAR(30) NOT NULL,min_value NUMERIC,max_value NUMERIC,color VARCHAR(20));
CREATE TABLE IF NOT EXISTS health_measurements(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,metric_id INTEGER NOT NULL REFERENCES metric_types(id),value NUMERIC(12,3) NOT NULL,measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),source VARCHAR(60) DEFAULT 'Вручную',comment TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS measurements_patient_time_idx ON health_measurements(patient_id,measured_at DESC);
CREATE TABLE IF NOT EXISTS lab_tests(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,clinic_id INTEGER REFERENCES clinics(id),taken_on DATE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'Готов',document_name TEXT);
CREATE TABLE IF NOT EXISTS lab_test_results(id BIGSERIAL PRIMARY KEY,test_id BIGINT NOT NULL REFERENCES lab_tests(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,value NUMERIC(12,3) NOT NULL,unit VARCHAR(40) NOT NULL,reference_min NUMERIC,reference_max NUMERIC);
CREATE TABLE IF NOT EXISTS medical_records(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,record_type VARCHAR(60) NOT NULL,title VARCHAR(180) NOT NULL,description TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),author_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS recommendations(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,category VARCHAR(60) NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,basis TEXT DEFAULT '',status VARCHAR(30) NOT NULL DEFAULT 'Новая',is_custom BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE recommendations ADD COLUMN IF NOT EXISTS is_custom BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS ai_conversations(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_messages(id BIGSERIAL PRIMARY KEY,conversation_id BIGINT NOT NULL REFERENCES ai_conversations(id) ON DELETE CASCADE,sender VARCHAR(20) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind VARCHAR(60) NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,related_type VARCHAR(50),related_id BIGINT,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS access_grants(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,doctor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(patient_id,doctor_id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),action VARCHAR(100) NOT NULL,entity VARCHAR(60),entity_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS doctor_schedules(id BIGSERIAL PRIMARY KEY,doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,weekday SMALLINT NOT NULL CHECK(weekday BETWEEN 1 AND 7),starts_at TIME NOT NULL,ends_at TIME NOT NULL,slot_minutes SMALLINT NOT NULL DEFAULT 30 CHECK(slot_minutes BETWEEN 5 AND 180),is_active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(doctor_id,weekday),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS medical_documents(id BIGSERIAL PRIMARY KEY,record_id BIGINT REFERENCES medical_records(id) ON DELETE CASCADE,lab_test_id BIGINT REFERENCES lab_tests(id) ON DELETE CASCADE,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 1572864),content BYTEA NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(record_id IS NOT NULL OR lab_test_id IS NOT NULL));
ALTER TABLE recommendations ADD COLUMN IF NOT EXISTS is_custom BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE recommendations ADD COLUMN IF NOT EXISTS due_date DATE;
CREATE INDEX IF NOT EXISTS medical_documents_record_idx ON medical_documents(record_id);
CREATE INDEX IF NOT EXISTS medical_documents_lab_idx ON medical_documents(lab_test_id);

ALTER TABLE users ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;

CREATE TABLE IF NOT EXISTS vaccinations(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,record_id BIGINT UNIQUE REFERENCES medical_records(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,administered_on DATE,manufacturer VARCHAR(180),notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS allergies(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,record_id BIGINT UNIQUE REFERENCES medical_records(id) ON DELETE CASCADE,substance VARCHAR(180) NOT NULL,severity VARCHAR(60) DEFAULT 'Не указана',notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS chronic_conditions(id BIGSERIAL PRIMARY KEY,patient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,record_id BIGINT UNIQUE REFERENCES medical_records(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,diagnosed_on DATE,notes TEXT DEFAULT '');

ALTER TABLE medical_records ADD COLUMN IF NOT EXISTS is_editable BOOLEAN NOT NULL DEFAULT FALSE;
